def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] != 0:
                        seen[yy][xx] = True
                        stack.append((yy, xx))
            extents = {}
            for y, x in component:
                color = grid[y][x]
                if color not in extents:
                    extents[color] = [y, y, x, x]
                else:
                    b = extents[color]
                    b[0] = min(b[0], y); b[1] = max(b[1], y)
                    b[2] = min(b[2], x); b[3] = max(b[3], x)
            layers = sorted(extents, key=lambda color: (-(extents[color][1]-extents[color][0]+1)*(extents[color][3]-extents[color][2]+1), color))
            mapping = {color: layers[-1-i] for i, color in enumerate(layers)}
            for y, x in component:
                out[y][x] = mapping[grid[y][x]]
    return out
